altitude.jitterFunction:
export function archipelagoAltitude(worldSeed, layoutVersion, cellX, cellZ, tier, sizeY) {
  const band = bandFor(worldSeed, layoutVersion, cellX, cellZ, tier);
  const span = band.maxY - band.minY + 1;
  const coarse = hash([worldSeed, layoutVersion, cellX, cellZ, 'altitude']) % span;
  // Ridge term: neighbouring cells drift together, so the band reads as a
  // sloping shelf instead of per-cell noise. Integer only, no trig, and the
  // double-modulo keeps the result in -4..4 for negative cell coordinates.
  const ridge = ((((cellX * 7 + cellZ * 13) % 9) + 9) % 9) - 4;
  const ceiling = Math.min(band.maxY, ARCHIPELAGO_CONFIG.absoluteMaxTopY - sizeY + 1);
  const floor = Math.max(band.minY, ARCHIPELAGO_CONFIG.absoluteMinY);
  return Math.min(ceiling, Math.max(floor, band.minY + coarse + ridge));
}
